+		return wordPart{}, false
+	}
+	switch t.peek() {
+	case '(':
+		t.advance()
+		startLine, startCol := t.line, t.col
+		script, err := t.readCommandSub()
+		if err != nil {
+			panic(&parseError{
+				input:   t.input,
+				line:    startLine,
+				col:     startCol,
+				message: err.Error(),
+			})
+		}
+		return wordPart{kind: partCommandSub, text: script, quoted: quoted}, true
+	case '{':
+		t.advance()
+		start := t.index
+		for !t.eof() && t.peek() != '}' {
+			t.advance()
