/workspace/parser.go.content:
package main

import (
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

type tokenType int

const (
	tokenEOF tokenType = iota
	tokenWord
	tokenSemi
	tokenPipe
	tokenAndIf
	tokenOrIf
	tokenRedirectIn
	tokenRedirectOut
	tokenRedirectAppend
	tokenBad
)

type partKind int

const (
	partLiteral partKind = iota
	partVariable
	partCommandSub
)

type wordPart struct {
	kind   partKind
	text   string
	quoted bool
}

type wordNode struct {
	parts         []wordPart
	tildeEligible bool
	globEligible  bool
}

type redirectNode struct {
	kind tokenType
	word wordNode
}

type commandNode struct {
	words     []wordNode
	redirects []redirectNode
}

type pipelineNode struct {
	commands []commandNode
}

type andOrRest struct {
	op       tokenType
	pipeline pipelineNode
}

type andOrNode struct {
	first pipelineNode
	rest  []andOrRest
}

type scriptNode struct {
	nodes []andOrNode
}

type token struct {
	typ  tokenType
	word wordNode
	text string
	line int
	col  int
}

type parseError struct {
	input   string
	line    int
	col     int
	message string
}

func (e *parseError) Error() string {
	lineText := sourceLine(e.input, e.line)
	return fmt.Sprintf("nsh: parse error:  --> %d:%d\n  |\n%d | %s\n  | %s^---\n  |\n  = %s\n",
		e.line, e.col, e.line, lineText, strings.Repeat(" ", max(0, e.col-1)), e.message)
}

type tokenizer struct {
	input string
	index int
	line  int
	col   int
}

func newTokenizer(input string) *tokenizer {
	return &tokenizer{
		input: input,
		line:  1,
		col:   1,
	}
}

func parseScript(input string) (*scriptNode, *parseError) {
	p := &parser{tz: newTokenizer(input), input: input}
	return p.parse()
}

type parser struct {
	tz    *tokenizer
	input string
	peek  *token
}

func (p *parser) parse() (*scriptNode, *parseError) {
	node := &scriptNode{}
	p.skipSeparators()
	if tok := p.peekToken(); tok.typ == tokenEOF {
		return node, nil
	}

	for {
		andOr, err := p.parseAndOr()
		if err != nil {
			return nil, err
		}
		node.nodes = append(node.nodes, andOr)

		tok := p.peekToken()
		if tok.typ == tokenEOF {
			break
		}
		if tok.typ != tokenSemi {
			return nil, p.unexpected(tok, "expected command")
		}
		p.nextToken()
		p.skipSeparators()
		if p.peekToken().typ == tokenEOF {
			break
		}
	}
	return node, nil
}

func (p *parser) parseAndOr() (andOrNode, *parseError) {
	first, err := p.parsePipeline()
	if err != nil {
		return andOrNode{}, err
	}
	node := andOrNode{first: first}
	for {
		tok := p.peekToken()
		if tok.typ != tokenAndIf && tok.typ != tokenOrIf {
			return node, nil
		}
		p.nextToken()
		nextPipe, perr := p.parsePipeline()
		if perr != nil {
			return andOrNode{}, perr
		}
		node.rest = append(node.rest, andOrRest{
			op:       tok.typ,
			pipeline: nextPipe,
		})
	}
}

func (p *parser) parsePipeline() (pipelineNode, *parseError) {
	cmd, err := p.parseCommand()
	if err != nil {
		return pipelineNode{}, err
	}
	pipe := pipelineNode{commands: []commandNode{cmd}}
	for p.peekToken().typ == tokenPipe {
		p.nextToken()
		nextCmd, perr := p.parseCommand()
		if perr != nil {
			return pipelineNode{}, perr
		}
		pipe.commands = append(pipe.commands, nextCmd)
	}
	return pipe, nil
}

func (p *parser) parseCommand() (commandNode, *parseError) {
	cmd := commandNode{}
	sawItem := false
	for {
		tok := p.peekToken()
		switch tok.typ {
		case tokenWord:
			p.nextToken()
			sawItem = true
			if len(cmd.words) == 0 {
				if reserved, ok := literalWord(tok.word); ok && isReservedWord(reserved) {
					return commandNode{}, &parseError{
						input:   p.input,
						line:    tok.line,
						col:     tok.col + utf8.RuneCountInString(reserved),
						message: "expected command or compound_list_sep",
					}
				}
			}
			cmd.words = append(cmd.words, tok.word)
		case tokenRedirectIn, tokenRedirectOut, tokenRedirectAppend:
			redirTok := p.nextToken()
			target := p.nextToken()
			if target.typ != tokenWord {
				return commandNode{}, p.unexpected(target, "expected redirect target")
			}
			sawItem = true
			cmd.redirects = append(cmd.redirects, redirectNode{
				kind: redirTok.typ,
				word: target.word,
			})
		case tokenBad:
			return commandNode{}, p.unexpected(tok, "expected command")
		default:
			if !sawItem {
				return commandNode{}, p.unexpected(tok, "expected command")
			}
			return cmd, nil
		}
	}
}

func (p *parser) skipSeparators() {
	for p.peekToken().typ == tokenSemi {
		p.nextToken()
	}
}

func (p *parser) peekToken() token {
	if p.peek == nil {
		tok := p.tz.next()
		p.peek = &tok
	}
	return *p.peek
}

func (p *parser) nextToken() token {
	tok := p.peekToken()
	p.peek = nil
	return tok
}

func (p *parser) unexpected(tok token, message string) *parseError {
	line := tok.line
	col := tok.col
	if tok.typ == tokenEOF {
		line = p.tz.line
		col = p.tz.col
	}
	return &parseError{
		input:   p.input,
		line:    line,
		col:     col,
		message: message,
	}
}

func (t *tokenizer) next() token {
	for {
		if t.eof() {
			return token{typ: tokenEOF, line: t.line, col: t.col}
		}
		ch := t.peek()
		switch ch {
		case ' ', '\t', '\r':
			t.advance()
		case '\n':
			line, col := t.line, t.col
			t.advance()
			return token{typ: tokenSemi, line: line, col: col}
		case '#':
			t.skipComment()
		case ';':
			line, col := t.line, t.col
			t.advance()
			return token{typ: tokenSemi, line: line, col: col}
		case '&':
			line, col := t.line, t.col
			t.advance()
			if !t.eof() && t.peek() == '&' {
				t.advance()
				return token{typ: tokenAndIf, line: line, col: col}
			}
			return token{typ: tokenBad, text: "&", line: line, col: col}
		case '|':
			line, col := t.line, t.col
			t.advance()
			if !t.eof() && t.peek() == '|' {
				t.advance()
				return token{typ: tokenOrIf, line: line, col: col}
			}
			return token{typ: tokenPipe, line: line, col: col}
		case '>':
			line, col := t.line, t.col
			t.advance()
			if !t.eof() && t.peek() == '>' {
				t.advance()
				return token{typ: tokenRedirectAppend, line: line, col: col}
			}
			return token{typ: tokenRedirectOut, line: line, col: col}
		case '<':
			line, col := t.line, t.col
			t.advance()
			return token{typ: tokenRedirectIn, line: line, col: col}
		case '(', ')':
			line, col := t.line, t.col
			text := string(ch)
			t.advance()
			return token{typ: tokenBad, text: text, line: line, col: col}
		default:
			return t.word()
		}
	}
}

func (t *tokenizer) word() token {
	line, col := t.line, t.col
	word := wordNode{
		tildeEligible: t.peek() == '~',
	}
	var literal strings.Builder
	literalQuoted := false

	flushLiteral := func() {
		if literal.Len() == 0 {
			return
		}
		word.parts = append(word.parts, wordPart{
			kind:   partLiteral,
			text:   literal.String(),
			quoted: literalQuoted,
		})
		literal.Reset()
	}

	appendLiteral := func(text string, quoted bool) {
		if literal.Len() > 0 && literalQuoted != quoted {
			flushLiteral()
		}
		literalQuoted = quoted
		literal.WriteString(text)
		if !quoted && strings.ContainsAny(text, "*?[") {
			word.globEligible = true
		}
	}

	for !t.eof() {
		ch := t.peek()
		if isWordBoundary(ch) {
			break
		}
		switch ch {
		case '\'':
			flushLiteral()
			t.advance()
			start := t.index
			for !t.eof() && t.peek() != '\'' {
				t.advance()
			}
			if t.eof() {
				panic(t.parseErr("expected closing single quote"))
			}
			appendLiteral(t.input[start:t.index], true)
			t.advance()
		case '"':
			flushLiteral()
			t.advance()
			for {
				if t.eof() {
					panic(t.parseErr("expected closing double quote"))
				}
				ch = t.peek()
				if ch == '"' {
					t.advance()
					break
				}
				if ch == '\\' {
					t.advance()
					if t.eof() {
						break
					}
					next := t.peek()
					switch next {
					case '$', '"', '\\':
						appendLiteral(string(next), true)
						t.advance()
					case '\n':
						t.advance()
					default:
						appendLiteral("\\"+string(next), true)
						t.advance()
					}
					continue
				}
				if ch == '$' {
					t.advance()
					if part, ok := t.variablePart(true); ok {
						flushLiteral()
						word.parts = append(word.parts, part)
						continue
					}
					appendLiteral("$", true)
					continue
				}
				appendLiteral(string(ch), true)
				t.advance()
			}
		case '\\':
			t.advance()
			if t.eof() {
				appendLiteral("\\", false)
				break
			}
			if t.peek() == '\n' {
				t.advance()
				continue
			}
			appendLiteral(string(t.peek()), false)
			t.advance()
		case '$':
			t.advance()
			if part, ok := t.variablePart(false); ok {
				flushLiteral()
				word.parts = append(word.parts, part)
			} else {
				appendLiteral("$", false)
			}
		default:
			appendLiteral(string(ch), false)
			t.advance()
		}
	}

	flushLiteral()
	return token{
		typ:  tokenWord,
		word: word,
		line: line,
		col:  col,
	}
}

func (t *tokenizer) variablePart(quoted bool) (wordPart, bool) {
	if t.eof() {
		return wordPart{}, false
	}
	switch t.peek() {
	case '(':
		t.advance()
		startLine, startCol := t.line, t.col
		script, err := t.readCommandSub()
		if err != nil {
			panic(&parseError{
				input:   t.input,
				line:    startLine,
				col:     startCol,
				message: err.Error(),
			})
		}
		return wordPart{kind: partCommandSub, text: script, quoted: quoted}, true
	case '{':
		t.advance()
		start := t.index
		for !t.eof() && t.peek() != '}' {
			t.advance()
		}
		if t.eof() {
			panic(t.parseErr("expected closing }"))
		}
		name := t.input[start:t.index]
		t.advance()
		return wordPart{kind: partVariable, text: name, quoted: quoted}, true
	case '#', '?':
		ch := t.peek()
		t.advance()
		return wordPart{kind: partVariable, text: string(ch), quoted: quoted}, true
	}

	if unicode.IsDigit(rune(t.peek())) {
		ch := t.peek()
		t.advance()
		return wordPart{kind: partVariable, text: string(ch), quoted: quoted}, true
	}

	if !isVarStart(t.peek()) {
		return wordPart{}, false
	}
	start := t.index
	t.advance()
	for !t.eof() && isVarContinue(t.peek()) {
		t.advance()
	}
	return wordPart{kind: partVariable, text: t.input[start:t.index], quoted: quoted}, true
}

func (t *tokenizer) readCommandSub() (string, error) {
	start := t.index
	depth := 1
	for !t.eof() {
		ch := t.peek()
		switch ch {
		case '\'':
			t.advance()
			for !t.eof() && t.peek() != '\'' {
				t.advance()
			}
			if t.eof() {
				return "", fmt.Errorf("expected closing single quote")
			}
			t.advance()
		case '"':
			t.advance()
			for !t.eof() {
				ch = t.peek()
				if ch == '"' {
					t.advance()
					break
				}
				if ch == '\\' {
					t.advance()
					if !t.eof() {
						t.advance()
					}
					continue
				}
				if ch == '$' {
					t.advance()
					if !t.eof() && t.peek() == '(' {
						t.advance()
						depth++
						continue
					}
					continue
				}
				t.advance()
			}
			if t.eof() {
				return "", fmt.Errorf("expected closing double quote")
			}
		case '\\':
			t.advance()
			if !t.eof() {
				t.advance()
			}
		case '$':
			t.advance()
			if !t.eof() && t.peek() == '(' {
				t.advance()
				depth++
			}
		case ')':
			t.advance()
			depth--
			if depth == 0 {
				return t.input[start : t.index-1], nil
			}
		default:
			t.advance()
		}
	}
	return "", fmt.Errorf("expected closing )")
}

func (t *tokenizer) skipComment() {
	for !t.eof() && t.peek() != '\n' {
		t.advance()
	}
}

func (t *tokenizer) parseErr(message string) *parseError {
	return &parseError{
		input:   t.input,
		line:    t.line,
		col:     t.col,
		message: message,
	}
}

func (t *tokenizer) eof() bool {
	return t.index >= len(t.input)
}

func (t *tokenizer) peek() byte {
	return t.input[t.index]
}

func (t *tokenizer) advance() {
	if t.eof() {
		return
	}
	_, size := utf8.DecodeRuneInString(t.input[t.index:])
	if size == 0 {
		size = 1
	}
	if t.input[t.index] == '\n' {
		t.line++
		t.col = 1
	} else {
		t.col++
	}
	t.index += size
}

func sourceLine(input string, line int) string {
	lines := strings.Split(input, "\n")
	if line <= 0 || line > len(lines) {
		return ""
	}
	return lines[line-1]
}

func isWordBoundary(ch byte) bool {
	switch ch {
	case ' ', '\t', '\r', '\n', ';', '|', '&', '>', '<':
		return true
	}
	return false
}

func isVarStart(ch byte) bool {
	return ch == '_' || unicode.IsLetter(rune(ch))
}

func isVarContinue(ch byte) bool {
	return ch == '_' || unicode.IsLetter(rune(ch)) || unicode.IsDigit(rune(ch))
}

func literalWord(word wordNode) (string, bool) {
	if len(word.parts) == 0 {
		return "", false
	}
	var b strings.Builder
	for _, part := range word.parts {
		if part.kind != partLiteral {
