package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
)

const defaultPrompt = `\{cyan}\{bold}\{current_dir} \$\{reset} `

type shell struct {
	stdin  io.Reader
	stdout io.Writer
	stderr io.Writer

	env        map[string]string
	aliases    map[string]string
	aliasOrder []string

	cwd    string
	home   string
	oldpwd string
	prompt string
	login  bool

	lastStatus int
}

type assignment struct {
	name  string
	value string
}

func newShell(stdin io.Reader, stdout, stderr io.Writer) (*shell, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return nil, err
	}

	env := map[string]string{}
	for _, entry := range os.Environ() {
		name, value, ok := strings.Cut(entry, "=")
		if ok {
			env[name] = value
		}
	}

	home := env["HOME"]
	if home == "" {
		if value, err := os.UserHomeDir(); err == nil {
			home = value
			env["HOME"] = value
		}
	}

	prompt := env["PROMPT"]
	if prompt == "" {
		prompt = defaultPrompt
	}

	return &shell{
		stdin:      stdin,
		stdout:     stdout,
		stderr:     stderr,
		env:        env,
		aliases:    map[string]string{},
		cwd:        cwd,
		home:       home,
		prompt:     prompt,
		lastStatus: 0,
	}, nil
}

func (s *shell) clone(stdout io.Writer) *shell {
	env := make(map[string]string, len(s.env))
	for key, value := range s.env {
		env[key] = value
	}
	aliases := make(map[string]string, len(s.aliases))
	for key, value := range s.aliases {
		aliases[key] = value
	}
	order := append([]string(nil), s.aliasOrder...)
	return &shell{
		stdin:      s.stdin,
		stdout:     stdout,
		stderr:     s.stderr,
		env:        env,
		aliases:    aliases,
		aliasOrder: order,
		cwd:        s.cwd,
		home:       s.home,
		oldpwd:     s.oldpwd,
		prompt:     s.prompt,
		login:      s.login,
		lastStatus: s.lastStatus,
	}
}

func (s *shell) ensureStateFiles() {
	if s.home == "" {
		return
	}
	logPath := filepath.Join(s.home, ".nsh.log")
	if _, err := os.OpenFile(logPath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644); err != nil {
		panicOpenHomeFile("~/.nsh.log", err)
	}
	historyPath := filepath.Join(s.home, ".nsh_history")
	if _, err := os.OpenFile(historyPath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644); err != nil {
		panicOpenHomeFile("~/.nsh_history", err)
	}
}

func (s *shell) loadRCFiles() int {
	var paths []string
	if s.home != "" {
		paths = append(paths, filepath.Join(s.home, ".nshrc"))
	}
	if xdg := s.env["XDG_CONFIG_HOME"]; xdg != "" {
		paths = append(paths, filepath.Join(xdg, "nsh", "nshrc"))
	}

	for _, path := range paths {
		content, err := os.ReadFile(path)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return 1
		}
		status, exited := s.executeStringWithIO(string(content), s.stdin, s.stdout, s.stderr)
		if exited {
			return status
		}
	}
	return 0
}

func (s *shell) executeString(script string) int {
	status, _ := s.executeStringWithIO(script, s.stdin, s.stdout, s.stderr)
	return status
}

func (s *shell) executeStringWithIO(script string, stdin io.Reader, stdout, stderr io.Writer) (status int, exited bool) {
	node, err := parseScriptSafe(script)
	if err != nil {
		fmt.Fprint(stderr, err.Error())
		s.lastStatus = 255
		return 255, false
	}
	return s.executeNode(node, stdin, stdout, stderr)
}

func (s *shell) executeNode(node *scriptNode, stdin io.Reader, stdout, stderr io.Writer) (status int, exited bool) {
	status = 0
	for _, andOr := range node.nodes {
		nextStatus, nextExited := s.runAndOr(andOr, stdin, stdout, stderr)
		status = nextStatus
		s.lastStatus = status
		if nextExited {
			return status, true
		}
	}
	return status, false
}

func (s *shell) repl() int {
	reader := bufio.NewReader(s.stdin)
	for {
		fmt.Fprint(s.stdout, s.renderPrompt())
		line, err := reader.ReadString('\n')
		if err == io.EOF {
			if line == "" {
				return 0
			}
		} else if err != nil {
			return 1
		}

		status, exited := s.executeStringWithIO(line, s.stdin, s.stdout, s.stderr)
		s.lastStatus = status
		if exited {
			return status
		}
		if err == io.EOF {
			return status
		}
	}
}

func (s *shell) runAndOr(node andOrNode, stdin io.Reader, stdout, stderr io.Writer) (int, bool) {
	status, exited := s.runPipeline(node.first, stdin, stdout, stderr)
	if exited {
		return status, true
	}

	for _, rest := range node.rest {
		if rest.op == tokenAndIf && status != 0 {
			continue
		}
		if rest.op == tokenOrIf && status == 0 {
			continue
		}
		status, exited = s.runPipeline(rest.pipeline, stdin, stdout, stderr)
		if exited {
			return status, true
		}
	}
	return status, false
}

func (s *shell) runPipeline(node pipelineNode, stdin io.Reader, stdout, stderr io.Writer) (int, bool) {
	if len(node.commands) == 1 {
		return s.runCommand(node.commands[0], stdin, stdout, stderr)
	}

	type result struct {
		index  int
		status int
		exited bool
	}

	results := make(chan result, len(node.commands))
	var wg sync.WaitGroup
	input := stdin

	for i, cmdNode := range node.commands {
		stageShell := s.clone(stdout)
		stageIn := input
		stageOut := stdout
		var pipeReader *io.PipeReader
		var pipeWriter *io.PipeWriter
		if i < len(node.commands)-1 {
			pipeReader, pipeWriter = io.Pipe()
			stageOut = pipeWriter
		}

		wg.Add(1)
		go func(index int, cmdNode commandNode, sh *shell, in io.Reader, out io.Writer, closer *io.PipeWriter) {
			defer wg.Done()
			status, exited := sh.runCommand(cmdNode, in, out, stderr)
			if closer != nil {
				closer.Close()
			}
			results <- result{index: index, status: status, exited: exited}
		}(i, cmdNode, stageShell, stageIn, stageOut, pipeWriter)

		if pipeReader != nil {
			input = pipeReader
		}
	}

	wg.Wait()
	close(results)

	lastStatus := 0
	lastExited := false
	for result := range results {
		if result.index == len(node.commands)-1 {
			lastStatus = result.status
			lastExited = result.exited
		}
	}
	return lastStatus, lastExited
}

func (s *shell) runCommand(node commandNode, stdin io.Reader, stdout, stderr io.Writer) (int, bool) {
	assignments, words := splitAssignments(node.words)
	words = s.expandAliases(words)

	localIn := stdin
	localOut := stdout
	closers := []io.Closer{}
	defer func() {
		for _, closer := range closers {
			closer.Close()
		}
	}()

	commandEnv := make(map[string]string, len(s.env))
	for key, value := range s.env {
		commandEnv[key] = value
	}
	for _, assignment := range assignments {
		commandEnv[assignment.name] = assignment.value
	}

	for _, redirect := range node.redirects {
		targets := s.expandWordToArgs(redirect.word)
		target := ""
		if len(targets) > 0 {
			target = targets[0]
		}
		if target == "" {
			target = "."
		}
		switch redirect.kind {
		case tokenRedirectIn:
			file, err := os.Open(s.resolvePath(target))
			if err != nil {
				fmt.Fprintf(stderr, "nsh: %v\n", err)
				return 1, false
			}
			closers = append(closers, file)
			localIn = file
		case tokenRedirectOut:
			file, err := os.OpenFile(s.resolvePath(target), os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
			if err != nil {
				fmt.Fprintf(stderr, "nsh: %v\n", err)
				return 1, false
			}
			closers = append(closers, file)
			localOut = file
		case tokenRedirectAppend:
			file, err := os.OpenFile(s.resolvePath(target), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
			if err != nil {
				fmt.Fprintf(stderr, "nsh: %v\n", err)
				return 1, false
			}
			closers = append(closers, file)
			localOut = file
		}
	}

	if len(words) == 0 {
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		return 0, false
	}

	args := s.expandWords(words)
	if len(args) == 0 {
		return 0, false
	}

	switch args[0] {
	case "exit":
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		return s.runExit(args[1:]), true
	case "cd":
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		return s.runCD(args[1:], stderr), false
	case "alias":
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		return s.runAlias(args[1:], localOut), false
	case "export":
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		return s.runExport(args[1:]), false
	case "pwd":
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		fmt.Fprintln(localOut, s.cwd)
		return 0, false
	}

	return s.runExternal(args, commandEnv, localIn, localOut, stderr), false
}

func (s *shell) runExit(args []string) int {
	if len(args) == 0 {
		return s.lastStatus
	}
	status, err := strconv.Atoi(args[0])
	if err != nil {
		return 1
	}
	return status
}

func (s *shell) runCD(args []string, stderr io.Writer) int {
	target := s.home
	if len(args) > 0 {
		target = args[0]
	}
	if target == "" {
		return 1
	}
	if target == "-" {
		if s.oldpwd == "" {
			return 1
		}
		target = s.oldpwd
	}
	target = s.expandTilde(target)
	resolved := s.resolvePath(target)
	oldpwd := s.cwd
	if err := os.Chdir(resolved); err != nil {
		if os.IsNotExist(err) {
			fmt.Fprintf(stderr, "nsh: cd: No such file or directory (os error 2): `%s'\n", target)
		} else {
			fmt.Fprintf(stderr, "nsh: cd: %v: `%s'\n", err, target)
		}
		return 1
	}
	s.oldpwd = oldpwd
	s.cwd = resolved
	return 0
}

func (s *shell) runAlias(args []string, stdout io.Writer) int {
	if len(args) == 0 {
		for _, name := range s.aliasOrder {
			fmt.Fprintf(stdout, "%s='%s'\n", name, s.aliases[name])
		}
		return 0
	}
	for _, arg := range args {
		name, value, ok := strings.Cut(arg, "=")
		if !ok || name == "" {
			if alias, exists := s.aliases[arg]; exists {
				fmt.Fprintf(stdout, "%s='%s'\n", arg, alias)
			}
			continue
		}
		s.setAlias(name, value)
	}
	return 0
}

func (s *shell) runExport(args []string) int {
	for _, arg := range args {
		if name, value, ok := strings.Cut(arg, "="); ok {
			s.setEnv(name, value)
			continue
		}
		if _, exists := s.env[arg]; !exists {
			s.env[arg] = ""
		}
	}
	return 0
}

func (s *shell) runExternal(args []string, env map[string]string, stdin io.Reader, stdout, stderr io.Writer) int {
	path, err := lookupExecutable(args[0], env["PATH"], s.cwd)
	if err != nil {
		fmt.Fprintf(stderr, "nsh: command not found `%s'\n", args[0])
		return 1
	}
	cmd := exec.Command(path, args[1:]...)
	cmd.Dir = s.cwd
	cmd.Env = envList(env)
	cmd.Stdin = stdin
	cmd.Stdout = stdout
	cmd.Stderr = stderr
	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			return exitErr.ExitCode()
		}
		return 1
	}
	return 0
}

func (s *shell) expandAliases(words []wordNode) []wordNode {
	if len(words) == 0 {
		return words
	}
	assignments, rest := splitAssignments(words)
	if len(rest) == 0 {
		return words
	}
	current := append([]wordNode(nil), rest...)
	for i := 0; i < 16; i++ {
		name, ok := literalWord(current[0])
		if !ok {
			break
		}
		aliasText, exists := s.aliases[name]
		if !exists {
			break
		}
		replacement, ok := parseAliasWords(aliasText)
		if !ok || len(replacement) == 0 {
			break
		}
		current = append(append([]wordNode(nil), replacement...), current[1:]...)
	}
	result := make([]wordNode, 0, len(assignments)+len(current))
	for _, assignment := range assignments {
		result = append(result, assignmentWord(assignment))
	}
	result = append(result, current...)
	return result
}

func (s *shell) expandWords(words []wordNode) []string {
	var args []string
	for _, word := range words {
		args = append(args, s.expandWordToArgs(word)...)
	}
	return args
}

func (s *shell) expandWordToArgs(word wordNode) []string {
	value := s.expandWord(word)
	if word.globEligible {
		if matches := s.expandGlob(value); len(matches) > 0 {
			return matches
		}
	}
	return []string{value}
}

func (s *shell) expandWord(word wordNode) string {
	var b strings.Builder
	for _, part := range word.parts {
		switch part.kind {
		case partLiteral:
			b.WriteString(part.text)
		case partVariable:
			b.WriteString(s.expandVariable(part.text))
		case partCommandSub:
			b.WriteString(s.expandCommandSub(part.text))
		}
	}
	value := b.String()
	if word.tildeEligible {
		value = s.expandTilde(value)
	}
	return value
}

func (s *shell) expandVariable(name string) string {
	switch name {
	case "#":
		return "0"
	case "?":
		return strconv.Itoa(s.lastStatus)
	}
	if len(name) == 1 && name[0] >= '0' && name[0] <= '9' {
		return ""
	}
	return s.env[name]
}

func (s *shell) expandCommandSub(script string) string {
	var out bytes.Buffer
	clone := s.clone(&out)
	clone.stdin = bytes.NewReader(nil)
	clone.executeStringWithIO(script, clone.stdin, &out, s.stderr)
	return strings.TrimRight(out.String(), "\n")
}

func (s *shell) expandTilde(value string) string {
	if value == "~" {
		return s.home
	}
	if strings.HasPrefix(value, "~/") {
		return filepath.Join(s.home, value[2:])
	}
	return value
}

func (s *shell) expandGlob(pattern string) []string {
	if !strings.ContainsAny(pattern, "*?[") {
		return nil
	}
	if filepath.IsAbs(pattern) {
		matches, _ := filepath.Glob(pattern)
		return matches
	}
	matches, _ := filepath.Glob(filepath.Join(s.cwd, pattern))
	if len(matches) == 0 {
		return nil
	}
	rel := make([]string, 0, len(matches))
	for _, match := range matches {
		value, err := filepath.Rel(s.cwd, match)
		if err != nil {
			rel = append(rel, match)
			continue
		}
		rel = append(rel, value)
	}
	sort.Strings(rel)
	return rel
}

func (s *shell) resolvePath(path string) string {
	if filepath.IsAbs(path) {
		return path
	}
	return filepath.Join(s.cwd, path)
}

func (s *shell) setAlias(name, value string) {
	if _, exists := s.aliases[name]; !exists {
		s.aliasOrder = append(s.aliasOrder, name)
	}
	s.aliases[name] = value
}

func (s *shell) setEnv(name, value string) {
	s.env[name] = value
	switch name {
	case "PROMPT":
		s.prompt = value
	case "HOME":
		s.home = value
	}
}

func splitAssignments(words []wordNode) ([]assignment, []wordNode) {
	assignments := []assignment{}
	index := 0
	for index < len(words) {
		text, ok := literalWord(words[index])
		if !ok {
			break
		}
		name, value, ok := splitAssignment(text)
		if !ok {
			break
		}
		assignments = append(assignments, assignment{name: name, value: value})
		index++
	}
	return assignments, words[index:]
}

func splitAssignment(text string) (string, string, bool) {
	name, value, ok := strings.Cut(text, "=")
	if !ok || name == "" {
		return "", "", false
	}
	for i, r := range name {
		if i == 0 {
			if !(r == '_' || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z')) {
				return "", "", false
			}
			continue
		}
		if !(r == '_' || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9')) {
			return "", "", false
		}
	}
	return name, value, true
}

func assignmentWord(assign assignment) wordNode {
	return wordNode{
		parts: []wordPart{{kind: partLiteral, text: assign.name + "=" + assign.value}},
	}
}

func parseAliasWords(text string) ([]wordNode, bool) {
	node, err := parseScriptSafe(text)
	if err != nil || len(node.nodes) != 1 {
		return nil, false
	}
	andOr := node.nodes[0]
	if len(andOr.rest) != 0 || len(andOr.first.commands) != 1 {
		return nil, false
	}
	return andOr.first.commands[0].words, true
}

func lookupExecutable(name, pathEnv, cwd string) (string, error) {
	if strings.ContainsRune(name, '/') {
		path := name
		if !filepath.IsAbs(path) {
			path = filepath.Join(cwd, path)
		}
		if isExecutable(path) {
			return path, nil
		}
		return "", os.ErrNotExist
	}

	for _, dir := range filepath.SplitList(pathEnv) {
		if dir == "" {
			dir = "."
		}
		path := filepath.Join(dir, name)
		if !filepath.IsAbs(path) {
			path = filepath.Join(cwd, path)
		}
		if isExecutable(path) {
			return path, nil
		}
	}
	return "", os.ErrNotExist
}

func isExecutable(path string) bool {
	info, err := os.Stat(path)
	if err != nil || info.IsDir() {
		return false
	}
	return info.Mode()&0o111 != 0
}

func envList(env map[string]string) []string {
	keys := make([]string, 0, len(env))
	for key := range env {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	values := make([]string, 0, len(keys))
	for _, key := range keys {
		values = append(values, key+"="+env[key])
	}
	return values
}

func panicOpenHomeFile(display string, err error) {
	fmt.Fprintln(os.Stderr)
	fmt.Fprintf(os.Stderr, "thread 'main' (%d) panicked at src/main.rs:165:10:\n", os.Getpid())
	fmt.Fprintf(os.Stderr, "failed to open %s: %v\n", display, err)
	fmt.Fprintln(os.Stderr, "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace")
	os.Exit(101)
}

func (s *shell) renderPrompt() string {
	return s.expandPromptString(s.prompt)
}

func (s *shell) expandPromptString(input string) string {
	var b strings.Builder
	for i := 0; i < len(input); {
		if input[i] != '\\' {
			b.WriteByte(input[i])
			i++
			continue
		}
		if strings.HasPrefix(input[i:], `\if{`) {
			cond, thenExpr, elseExpr, next, ok := parsePromptIf(input, i)
			if ok {
				if s.promptCondition(cond) {
					b.WriteString(s.expandPromptString(thenExpr))
				} else {
					b.WriteString(s.expandPromptString(elseExpr))
				}
				i = next
				continue
			}
		}
		if strings.HasPrefix(input[i:], `\{`) {
			end := strings.IndexByte(input[i+2:], '}')
			if end >= 0 {
				token := input[i+2 : i+2+end]
				b.WriteString(s.promptToken(token))
				i += end + 3
				continue
			}
		}
		if strings.HasPrefix(input[i:], `\n`) {
			b.WriteByte('\n')
			i += 2
			continue
		}
		if strings.HasPrefix(input[i:], `\$`) {
			b.WriteByte('$')
			i += 2
			continue
		}
		if i+1 < len(input) {
			b.WriteByte(input[i+1])
			i += 2
			continue
		}
		b.WriteByte(input[i])
		i++
	}
	return b.String()
}

func (s *shell) promptToken(token string) string {
	switch token {
	case "username":
		if user := s.env["USER"]; user != "" {
			return user
		}
		return "unknown"
	case "hostname":
		name, err := os.Hostname()
		if err != nil {
			return ""
		}
		return name
	case "current_dir":
		return s.promptCurrentDir()
	case "repo_status":
		status, ok := s.repoStatus()
		if !ok {
			return ""
		}
		return status
	case "reset":
		return "\x1b[0m"
	case "bold":
		return "\x1b[1m"
	case "underline":
		return "\x1b[4m"
	case "red":
		return "\x1b[31m"
	case "blue":
		return "\x1b[34m"
	case "green":
		return "\x1b[32m"
	case "yellow":
		return "\x1b[33m"
	case "cyan":
		return "\x1b[36m"
	case "magenta":
		return "\x1b[35m"
	default:
		return ""
	}
}

func (s *shell) promptCurrentDir() string {
	if s.home == "" {
		return s.cwd
	}
	cleanHome := filepath.Clean(s.home)
	cleanCwd := filepath.Clean(s.cwd)
	if cleanCwd == cleanHome {
		return "~"
	}
	prefix := cleanHome + string(os.PathSeparator)
	if strings.HasPrefix(cleanCwd, prefix) {
		return "~/" + strings.TrimPrefix(cleanCwd, prefix)
	}
	return cleanCwd
}

func (s *shell) promptCondition(cond string) bool {
	switch cond {
	case "in_remote":
		return s.env["SSH_CLIENT"] != ""
	case "in_repo":
		_, ok := s.repoStatus()
		return ok
	default:
		return false
	}
}

func (s *shell) repoStatus() (string, bool) {
	branchCmd := exec.Command("git", "rev-parse", "--abbrev-ref", "HEAD")
	branchCmd.Dir = s.cwd
	branchCmd.Env = envList(s.env)
	branchOut, err := branchCmd.Output()
	if err != nil {
		return "", false
	}
	branch := strings.TrimSpace(string(branchOut))
	if branch == "" {
		return "", false
	}

	statusCmd := exec.Command("git", "status", "--porcelain", "--ignore-submodules=dirty")
	statusCmd.Dir = s.cwd
	statusCmd.Env = envList(s.env)
	statusOut, err := statusCmd.Output()
	if err == nil && strings.TrimSpace(string(statusOut)) != "" {
		branch += "*"
	}
	return branch, true
}

func parsePromptIf(input string, start int) (cond, thenExpr, elseExpr string, next int, ok bool) {
	index := start + len(`\if{`)
	value, nextIndex, ok := parsePromptBrace(input, index)
	if !ok {
		return "", "", "", start, false
	}
	cond = value
	if nextIndex >= len(input) || input[nextIndex] != '{' {
		return "", "", "", start, false
	}
	thenExpr, nextIndex, ok = parsePromptBrace(input, nextIndex+1)
	if !ok || nextIndex >= len(input) || input[nextIndex] != '{' {
		return "", "", "", start, false
	}
	elseExpr, nextIndex, ok = parsePromptBrace(input, nextIndex+1)
	if !ok {
		return "", "", "", start, false
	}
	return cond, thenExpr, elseExpr, nextIndex, true
}

func parsePromptBrace(input string, start int) (string, int, bool) {
	depth := 1
	var b strings.Builder
	for i := start; i < len(input); i++ {
		switch input[i] {
		case '{':
			depth++
			b.WriteByte(input[i])
		case '}':
			depth--
			if depth == 0 {
				return b.String(), i + 1, true
			}
			b.WriteByte(input[i])
		default:
			b.WriteByte(input[i])
		}
	}
	return "", start, false
}

