			return waitAndReturn(cmd)
		}

		nextMeta, readErr := readUntilMeta(reader)
		if readErr != nil {
			return waitAndReturn(cmd)
		}
		meta = nextMeta
	}
}

func renderPrompt(meta shellMeta, ctx promptContext) string {
	promptSpec := meta.prompt
	if !meta.promptSet {
		promptSpec = defaultPrompt
	}
	ctx.pwd = meta.pwd
	return renderPromptSpec(promptSpec, ctx)
}

func newPromptContext() promptContext {
	home, _ := resolveHome()
	hostname, _ := os.Hostname()
	return promptContext{
		home:     home,
		hostname: hostname,
		remote:   os.Getenv("SSH_CONNECTION") != "" || os.Getenv("SSH_CLIENT") != "" || os.Getenv("SSH_TTY") != "",
	}
}

func renderPromptSpec(spec string, ctx promptContext) string {
	var out strings.Builder
	for i := 0; i < len(spec); {
		switch {
		case strings.HasPrefix(spec[i:], `\n`):
			out.WriteByte('\n')
			i += 2
		case strings.HasPrefix(spec[i:], `\{`):
			end := strings.IndexByte(spec[i+2:], '}')
			if end == -1 {
				out.WriteByte(spec[i])
				i++
				continue
			}
			out.WriteString(promptTokenValue(spec[i+2:i+2+end], ctx))
			i += 3 + end
		case strings.HasPrefix(spec[i:], `\if{`):
			cond, next, ok := readBrace(spec, i+3)
			if !ok {
				out.WriteString(`\if`)
				i += 3
				continue
			}
			thenPart, next, ok := readBrace(spec, next)
			if !ok {
				out.WriteString(`\if`)
				i += 3
				continue
			}
			elsePart, next, ok := readBrace(spec, next)
			if !ok {
				out.WriteString(`\if`)
				i += 3
				continue
			}
			if promptCondition(cond, ctx) {
				out.WriteString(renderPromptSpec(thenPart, ctx))
			} else {
				out.WriteString(renderPromptSpec(elsePart, ctx))
			}
			i = next
		default:
			out.WriteByte(spec[i])
			i++
		}
	}
	return out.String()
}

func readBrace(spec string, start int) (string, int, bool) {
	if start >= len(spec) || spec[start] != '{' {
		return "", start, false
	}
	depth := 0
	for i := start; i < len(spec); i++ {
		switch spec[i] {
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				return spec[start+1 : i], i + 1, true
			}
		}
	}
	return "", start, false
}

func promptCondition(name string, ctx promptContext) bool {
	switch name {
	case "in_remote":
		return ctx.remote
	case "in_repo":
		_, ok := gitRepoStatus(ctx.pwd)
		return ok
	default:
		return false
	}
}

func promptTokenValue(name string, ctx promptContext) string {
	switch name {
	case "username":
		if user := os.Getenv("USER"); user != "" {
			return user
		}
		return "unknown"
	case "hostname":
		return ctx.hostname
	case "current_dir":
		return displayDir(ctx.pwd, ctx.home)
	case "reset":
		return "\x1b[0m"
	case "bold":
		return "\x1b[1m"
	case "underline":
		return "\x1b[4m"
	case "red":
		return "\x1b[31m"
	case "blue":
		return "\x1b[34m"
	case "green":
		return "\x1b[32m"
	case "yellow":
		return "\x1b[33m"
	case "cyan":
		return "\x1b[36m"
	case "magenta":
		return "\x1b[35m"
	case "repo_status":
		status, _ := gitRepoStatus(ctx.pwd)
		return status
	default:
		return ""
	}
}

func displayDir(pwd, home string) string {
	if home == "" {
		return pwd
	}
	if pwd == home {
		return "~"
	}
	if strings.HasPrefix(pwd, home+"/") {
		return "~" + pwd[len(home):]
	}
	return pwd
}

func gitRepoStatus(dir string) (string, bool) {
	if dir == "" {
		return "", false
	}

	headCmd := exec.Command("git", "rev-parse", "--abbrev-ref", "HEAD")
	headCmd.Dir = dir
	headOut, err := headCmd.Output()
	if err != nil {
		return "", false
	}

	name := strings.TrimSpace(string(headOut))
	if name == "" {
		return "", false
	}

	statusCmd := exec.Command("git", "status", "--porcelain")
	statusCmd.Dir = dir
	statusOut, err := statusCmd.Output()
	if err == nil && len(bytes.TrimSpace(statusOut)) > 0 {
		name += "*"
	}

	return name, true
}

func preludeScript(opts options) string {
	var out strings.Builder
	out.WriteString("cd() {\n")
	out.WriteString("    case $# in\n")
	out.WriteString("        0) command cd; return $? ;;\n")
	out.WriteString("        1)\n")
	out.WriteString("            if command cd \"$1\" 2>/dev/null; then\n")
	out.WriteString("                return 0\n")
	out.WriteString("            fi\n")
	out.WriteString("            printf \"nsh: cd: No such file or directory (os error 2): `%s'\\n\" \"$1\" >&2\n")
	out.WriteString("            return 1\n")
	out.WriteString("            ;;\n")
	out.WriteString("        *) command cd \"$@\"; return $? ;;\n")
	out.WriteString("    esac\n")
	out.WriteString("}\n")

	if !opts.norc {
		for _, rcPath := range rcPaths() {
			out.WriteString("[ -f ")
			out.WriteString(shellQuote(rcPath))
			out.WriteString(" ] && . ")
			out.WriteString(shellQuote(rcPath))
			out.WriteByte('\n')
		}
	}

	return out.String()
}

func rcPaths() []string {
	home, ok := resolveHome()
	if !ok || home == "" {
		return nil
	}

	xdg := os.Getenv("XDG_CONFIG_HOME")
	if xdg == "" {
		xdg = filepath.Join(home, ".config")
	}

	return []string{
		filepath.Join(home, ".nshrc"),
		filepath.Join(xdg, "nsh", "nshrc"),
	}
}

func resolveHome() (string, bool) {
	if home := os.Getenv("HOME"); home != "" {
		return home, true
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", false
	}
	return home, true
}

func touchLog() {
	touchUserFile(".nsh.log")
}

func touchHistory() {
	touchUserFile(".nsh_history")
}

func touchUserFile(name string) {
	home, ok := resolveHome()
	if !ok || home == "" {
		return
	}
	path := filepath.Join(home, name)
	file, err := os.OpenFile(path, os.O_RDONLY|os.O_CREATE, 0o644)
	if err != nil {
		return
	}
	_ = file.Close()
}

func writeLogMessage(message string) {
	home, ok := resolveHome()
	if !ok || home == "" {
		return
	}
	path := filepath.Join(home, ".nsh.log")
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0o644)
	if err != nil {
		return
	}
	defer file.Close()
	_, _ = io.WriteString(file, message)
}

func ensureReadableFile(path string) error {
	file, err := os.Open(path)
	if err != nil {
		return err
	}
	return file.Close()
}

func panicLikeOpenFailure(path string, err error) int {
	message := fmt.Sprintf("nsh: panicked at src/main.rs:114:34:\nfailed to open the file: %v\n\nnsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues\n", err)
	fmt.Fprint(os.Stderr, message)
	writeLogMessage(message)
	_ = path
	return 101
}

func isTTY(file *os.File) bool {
	info, err := file.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice != 0
}

func shellQuote(input string) string {
	if input == "" {
		return "''"
	}
	return "'" + strings.ReplaceAll(input, "'", `'\''`) + "'"
}

func exitCodeFromErr(err error) int {
	if err == nil {
		return 0
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		return exitErr.ExitCode()
	}
	return 1
}

func writeTempPrelude(content string) (string, error) {
	file, err := os.CreateTemp("", "nsh-prelude-*.sh")
	if err != nil {
		return "", err
	}
	defer file.Close()
	if _, err := file.WriteString(content); err != nil {
		return "", err
	}
	return file.Name(), nil
}

func combinedPipe() (*bufio.Reader, *os.File, error) {
	reader, writer, err := os.Pipe()
	if err != nil {
		return nil, nil, err
	}
	return bufio.NewReader(reader), writer, nil
}

func metaQuery() string {
	return "__nsh_status=$?\n" +
		"if [ \"${PROMPT+x}\" ]; then __nsh_prompt_set=1; else __nsh_prompt_set=0; fi\n" +
		"printf '%s\\036%s\\036%s\\036%s\\036' '" + metaSentinel + "' \"$__nsh_status\" \"$PWD\" \"$__nsh_prompt_set\"\n" +
		"if [ \"$__nsh_prompt_set\" = 1 ]; then printf '%s' \"$PROMPT\"; fi\n" +
		"printf '\\n'\n"
}

func readUntilMeta(reader *bufio.Reader) (shellMeta, error) {
	var meta shellMeta
	sentinel := []byte(metaSentinel + "\x1e")

	for {
		chunk, err := reader.ReadBytes('\n')
		if len(chunk) > 0 {
			index := bytes.Index(chunk, sentinel)
			if index >= 0 {
				if index > 0 {
					_, _ = os.Stdout.Write(chunk[:index])
				}
				line := strings.TrimSuffix(string(chunk[index+len(sentinel):]), "\n")
				parts := strings.SplitN(line, "\x1e", 4)
				if len(parts) == 4 {
					if status, convErr := strconv.Atoi(parts[0]); convErr == nil {
						meta.status = status
					}
					meta.pwd = parts[1]
					meta.promptSet = parts[2] == "1"
					meta.prompt = parts[3]
					return meta, nil
				}
			}
			_, _ = os.Stdout.Write(chunk)
		}
		if err != nil {
			return meta, err
		}
	}
}

func waitAndReturn(cmd *exec.Cmd) int {
	err := cmd.Wait()
	return exitCodeFromErr(err)
}

